// Pega o CSV como texto vindo do HTTP Request

const csvRaw = $json.data ?? $json.body ?? $json;

const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);



const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

const headers = lines[0].split(",").map(h => h.trim());



const investimentos = lines.slice(1).map(line => {

  const cols = line.split(",").map(c => c.trim());

  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");



  // normaliza mínimo para número

  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;



  return obj;

});



return [{ json: { investimentos } }];

const entrada = $input.first().json;

const clientes = entrada.body?.clientes ?? entrada.clientes ?? [];

const resultados = clientes.map(cliente => {
  const saldoTexto = cliente.saldo || "R$ 0,00";

  const saldoNum = Number(
    saldoTexto
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .trim()
  ) || 0;

  let recomendacao;

  if (cliente.perfil === "Conservador") {
    recomendacao = {
      perfil: "Conservador",
      produto: "CDB Liquidez Diária",
      minimo: 1000,
      rentabilidade: "12.5%",
      motivo: "saldo_ok"
    };
  } else if (cliente.perfil === "Moderado") {
    recomendacao = {
      perfil: "Moderado",
      produto: "CDB e fundos de investimento",
      minimo: 1000,
      rentabilidade: "A consultar",
      motivo: "perfil_moderado"
    };
  } else {
    recomendacao = {
      perfil: cliente.perfil || "Não informado",
      produto: "Fundos de investimento",
      minimo: 1000,
      rentabilidade: "A consultar",
      motivo: "perfil_arrojado"
    };
  }

  // Incluir a rentabilidade na mensagem
  const mensagem =
    `Olá ${cliente.nome}! Pelo seu perfil ${cliente.perfil}, ` +
    `uma opção a avaliar é o ${recomendacao.produto} ` +
    `(investimento mínimo de R$ ${recomendacao.minimo.toLocaleString("pt-BR", { minimumFractionDigits: 2 })}). ` +
    `Seu saldo atual é ${saldoTexto}. ` +
    `Rentabilidade informada: ${recomendacao.rentabilidade}.`;

  return {
    nome: cliente.nome,
    email: cliente.email,
    perfil: cliente.perfil,
    saldo_texto: saldoTexto,
    saldo_num: saldoNum,
    recomendacao,
    mensagens: [
      mensagem,
      `${cliente.nome}: recomendação para perfil ${cliente.perfil}: ` +
      `${recomendacao.produto}. Rentabilidade: ${recomendacao.rentabilidade}.`,
      mensagem
    ],
    mensagem_escolhida: mensagem
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: resultados.length,
    resultados
  }
}];

// 1. Extrai a lista de resultados vinda do nó anterior
const resultados = $json.resultados || [];

// 2. Função para converter valores em texto (R$) para formato numérico
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();

  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// 3. Mapeia cada cliente retornando a estrutura esperada pelo n8n
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

// 4. Retorna a lista tratada com os itens individuais
return out;

