const items = $input.all();

return items.map(item => {
  const j = item.json || {};

  // 1. Pega o texto gerado pela IA (suporta OpenAI, Gemini e Chat Model do n8n)
  let rawText = "";

  if (j.content && Array.isArray(j.content) && j.content[0]?.text) {
    // Formato padrão do nó da OpenAI/Gemini no n8n (o que apareceu no seu log)
    rawText = j.content[0].text;
  } else if (typeof j.content === 'string') {
    rawText = j.content;
  } else if (j.text) {
    rawText = j.text;
  } else if (j.output) {
    rawText = typeof j.output === 'string' ? j.output : JSON.stringify(j.output);
  } else {
    rawText = JSON.stringify(j);
  }

  // 2. Extrai o JSON removendo qualquer marcação residual de Markdown
  let parsed = {};
  try {
    const cleanJson = rawText
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    parsed = JSON.parse(cleanJson);
  } catch (e) {
    console.log("Erro no JSON.parse:", e);
  }

  // 3. Garante a formatação das quebras de linha (\n)
  let textBody = parsed.text_body || rawText;
  if (typeof textBody === 'string') {
    textBody = textBody.replace(/\\n/g, '\n');
  }

  let htmlBody = parsed.html_body || "";
  if (typeof htmlBody === 'string') {
    htmlBody = htmlBody.replace(/\\n/g, '<br>');
  }

  // 4. Retorna a estrutura perfeita para as colunas do n8n
  return {
    json: {
      ok: true,
      to: j.email_to || j.to || j.email || parsed.to || "",
      subject: parsed.subject || j.subject || "Sugestão de Investimento",
      text_body: textBody,
      html_body: htmlBody || `<p>${textBody.replace(/\n/g, '<br>')}</p>`
    }
  };
});;
